## Why This Is Asked
Tests practical offline-first data handling in React Native. It probes AsyncStorage usage, hook design, and clear cache invalidation logic that affects UX.

## Key Concepts
- AsyncStorage caching with TTL
- Custom React hook design: useCachedQuery
- Offline-first UX and error handling
- FlatList integration for data rendering

## Code Example
```javascript
import { useEffect, useState } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

export function useCachedQuery(key, fetchFn, ttl) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const cached = await AsyncStorage.getItem(key);
      if (cached) {
        const { value, ts } = JSON.parse(cached);
        if (Date.now() - ts < ttl) {
          setData(value);
          setLoading(false);
          return;
        }
      }
      const fresh = await fetchFn();
      await AsyncStorage.setItem(key, JSON.stringify({ value: fresh, ts: Date.now() }));
      setData(fresh);
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [key]);
  return { data, loading, error, refetch: load };
}
```

